36	)
37	
38	// stubImageNames makes the inventory load neither call docker nor drop the
39	// cached image: the machine "holds" exactly the given references.
40	func stubImageNames(t *testing.T, refs ...string) {
41		t.Helper()
42		old := docker.ImageNames
43		docker.ImageNames = func() (map[string]struct{}, bool) {
44			out := map[string]struct{}{}
45			for _, r := range refs {
46				out[r] = struct{}{}
47			}
48			return out, true
49		}
50		t.Cleanup(func() { docker.ImageNames = old })
51	}
52	
53	// seedSecCaches writes one scanned repository (context "default") and one
54	// scanned image into the isolated HOME and returns the repository's path.
55	func seedSecCaches(t *testing.T) string {
56		t.Helper()
57		if got := config.CurrentContextName(); got != "default" {
58			t.Fatalf("config.CurrentContextName() = %q under the isolated HOME, the seed assumes \"default\"", got)
59		}
60		repo := filepath.Join(t.TempDir(), secRepoName)
61		if err := os.MkdirAll(filepath.Join(repo, ".git"), 0o755); err != nil {
62			t.Fatal(err)
63		}
64		at := time.Now().Add(-time.Hour)
65		wc, err := cache.NewWorkspaceScanCache("default")
66		if err != nil {
67			t.Fatal(err)
68		}
69		if err := wc.Set(repo, cache.WorkspaceScanEntry{RepoPath: repo, Critical: 1, ScannedAt: at}); err != nil {
70			t.Fatal(err)
71		}
72		ic, err := cache.NewImageScanCache()
73		if err != nil {
74			t.Fatal(err)
75		}
76		if err := ic.Set(secImage, cache.ImageScanEntry{High: 2, ScannedAt: at}); err != nil {
77			t.Fatal(err)
78		}
79		return repo
80	}
81	
82	// secRouter is a router at width x 30 on an isolated HOME holding the two
83	// scanned targets, and the repository's path.
84	func secRouter(t *testing.T, width int) (*App, string) {
85		t.Helper()
86		testutil.FastTimers(t, &animationFastInterval)
87		a := routerAt(t, &bareView{}, width, 30)
88		stubImageNames(t, secImage)
89		return a, seedSecCaches(t)
90	}
